#include <stdio.h>
#include <stdlib.h>
#include "list.h"

/* "static" keeps these helper names private to this file, so they can't clash with names in your own files. */

/* ------------------------------------------------------------------ */
/* Shared helper used by all four candidates                           */
/* ------------------------------------------------------------------ */
static Node *split_list(Node *head) {
    if (head == NULL || head->next == NULL) return NULL;
    Node *slow = head;
    Node *fast = head->next;
    while (fast != NULL && fast->next != NULL) {
        slow = slow->next;
        fast = fast->next->next;
    }
    Node *second = slow->next;
    slow->next = NULL;
    return second;
}

/* ------------------------------------------------------------------ */
/* Candidate 1                                                         */
/* ------------------------------------------------------------------ */
static Node *merge1(Node *a, Node *b) {
    Node dummy;
    Node *tail = &dummy;
    dummy.next = NULL;
    while (a != NULL && b != NULL) {
        if (a->key <= b->key) {
            tail->next = a;
            a = a->next;
        } else {
            tail->next = b;
            b = b->next;
        }
        tail = tail->next;
    }
    if (a != NULL) tail->next = a;
    return dummy.next;
}

static Node *sort1(Node *head) {
    if (head == NULL || head->next == NULL) return head;
    Node *second = split_list(head);
    head = sort1(head);
    second = sort1(second);
    return merge1(head, second);
}

Node *ai_sort_1(Node *head) {
    return sort1(head);
}

/* ------------------------------------------------------------------ */
/* Candidate 2                                                         */
/* ------------------------------------------------------------------ */
static Node *merge2(Node *a, Node *b) {
    Node dummy;
    Node *tail = &dummy;
    dummy.next = NULL;
    while (a != NULL && b != NULL) {
        if (a->key < b->key) {
            tail->next = a;
            a = a->next;
        } else {
            tail->next = b;
            b = b->next;
        }
        tail = tail->next;
    }
    tail->next = (a != NULL) ? a : b;
    return dummy.next;
}

static Node *sort2(Node *head) {
    if (head == NULL || head->next == NULL) return head;
    Node *second = split_list(head);
    head = sort2(head);
    second = sort2(second);
    return merge2(head, second);
}

Node *ai_sort_2(Node *head) {
    return sort2(head);
}

/* ------------------------------------------------------------------ */
/* Candidate 3                                                         */
/* ------------------------------------------------------------------ */
static Node *append_node(Node *result, Node *node) {
    node->next = NULL;
    if (result == NULL) return node;
    Node *cur = result;
    while (cur->next != NULL) cur = cur->next;
    cur->next = node;
    return result;
}

static Node *merge3(Node *a, Node *b) {
    Node *result = NULL;
    while (a != NULL && b != NULL) {
        Node *take;
        if (a->key <= b->key) {
            take = a;
            a = a->next;
        } else {
            take = b;
            b = b->next;
        }
        result = append_node(result, take);
    }
    while (a != NULL) {
        Node *next = a->next;
        result = append_node(result, a);
        a = next;
    }
    while (b != NULL) {
        Node *next = b->next;
        result = append_node(result, b);
        b = next;
    }
    return result;
}

static Node *sort3(Node *head) {
    if (head == NULL || head->next == NULL) return head;
    Node *second = split_list(head);
    head = sort3(head);
    second = sort3(second);
    return merge3(head, second);
}

Node *ai_sort_3(Node *head) {
    return sort3(head);
}

/* ------------------------------------------------------------------ */
/* Candidate 4                                                         */
/* ------------------------------------------------------------------ */
static Node *merge4(Node *a, Node *b) {
    if (a == NULL) return b;
    if (b == NULL) return a;
    if (a->key <= b->key) {
        a->next = merge4(a->next, b);
        return a;
    } else {
        b->next = merge4(a, b->next);
        return b;
    }
}

static Node *sort4(Node *head) {
    if (head == NULL || head->next == NULL) return head;
    Node *second = split_list(head);
    head = sort4(head);
    second = sort4(second);
    return merge4(head, second);
}

Node *ai_sort_4(Node *head) {
    return sort4(head);
}
